searchUrl:
@js:
var root = 'https://www.cool18.com/bbs4/index.php';
var term = String(key).trim();
var url;
if (term === '最新') {
    if (Number(page) <= 1) {
        source.put('cool18LatestCursor', '');
        url = root;
    } else {
        var cursor = String(source.get('cool18LatestCursor'));
        if (!/^[0-9]+$/.test(cursor)) throw new Error('请重新搜索“最新”后顺序翻页');
        url = root + '?app=forum&act=ajax&mtid=' + cursor + '&aifilter=0';
    }
} else {
    url = root + '?action=search&bbsdr=bbs4&act=threadsearch&app=forum&keywords=' + encodeURIComponent(term) + '&submit=%E6%9F%A5%E8%AF%A2&first=1&p=' + page;
}
url;

ruleSearch.bookList:
@js:
var html = String(result);
var embedded = html.match(/\b_PageData\s*=\s*(\[[^\r\n]*\])\s*;/);
var doc = org.jsoup.Jsoup.parse(html);
var books;
if (embedded || /^\s*\[/.test(html)) {
    var rows = JSON.parse(embedded ? embedded[1] : html);
    if (!Array.isArray(rows)) throw new Error('最新帖子数据格式错误');
    var listDoc = org.jsoup.Jsoup.parse('<ul></ul>');
    var list = listDoc.select('ul').first();
    var cursor = 0;
    for (var i = 0; i < rows.length; i++) {
        var row = rows[i];
        if (String(row.uptid) !== '0') continue;
        var subject = org.jsoup.Jsoup.parse(String(row.subject));
        subject.select('.list-type-show').remove();
        var li = list.appendElement('li');
        li.appendElement('a').attr('href', 'https://www.cool18.com/bbs4/index.php?app=forum&act=threadview&tid=' + row.tid).text(String(subject.text()));
        li.appendElement('font').text(String(row.username));
        li.appendElement('i').text(String(row.dateline));
        if (cursor === 0 || Number(row.tid) < cursor) cursor = Number(row.tid);
    }
    source.put('cool18LatestCursor', cursor ? String(cursor) : '');
    books = listDoc.select('li');
} else {
    books = doc.select('.thread-list > li:has(a[href*="act=threadview"])');
}
books;

