ruleToc.chapterList:
@js:
var doc = org.jsoup.Jsoup.parse(String(result));
var title = String(doc.select('h1.main-title').text());
var pageId = String(baseUrl).match(/[?&]tid=(\d+)/);
if (!pageId || !title) throw new Error('未取得帖子标题或编号');
var tid = pageId[1];
var info = String(doc.select('script:containsData(const threadInfo)').html());
var uid = info.match(/"uid"\s*:\s*"?(\d+)/);
if (!uid) throw new Error('未取得发帖者编号');
var bookName = title.match(/[【《]([^】》]+)[】》]/);
var key = bookName ? bookName[1] : title.replace(/(?:作者|作)\s*[:：].*$/, '').replace(/[（(].*$/, '').trim();
var prefix = 'https://www.cool18.com/bbs4/index.php?app=forum&act=threadview&tid=';
var rows = JSON.parse(String(java.ajax('https://www.cool18.com/bbs4/index.php?app=forum&act=achildlist&tid=' + tid)));
if (!Array.isArray(rows)) throw new Error('续文接口未返回列表');
var chapters = [{tid: tid, subject: title}];
rows.sort(function(a, b) { return Number(a.tid) - Number(b.tid); });
var seen = {};
seen[tid] = true;
for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    var subject = String(row.subject);
    var sameBook = key && subject.indexOf(key) >= 0;
    var numbered = /^(?:第[０-９0-9一二三四五六七八九十百千零〇两]+[章节回卷集部]|[（(]?[０-９0-9]+[）).、:：]|续[文篇]?|正文)/.test(subject);
    if (String(row.uid) === uid[1] && Number(row.size) > 0 && (sameBook || numbered) && !seen[row.tid]) {
        chapters.push(row);
        seen[row.tid] = true;
    }
}
var toc = org.jsoup.Jsoup.parse('<ul></ul>');
var list = toc.select('ul').first();
for (var j = 0; j < chapters.length; j++) {
    list.appendElement('li').appendElement('a').attr('href', prefix + chapters[j].tid).text(String(chapters[j].subject));
}
toc.select('li');
